import torch, json
E=W('model.embed_tokens.weight')
def ids(words):
    out=[]
    for w in words:
        for v in [w,' '+w]:
            t=encode(v)
            if len(t)==1: out.append(t[0])
    return sorted(set(out))
cats={
 'weekday':['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],
 'month':['January','February','March','April','May','June','July','August','September','October','November','December'],
 'ordinal':['first','second','third','fourth','fifth','sixth','seventh','eighth','ninth','tenth'],
 'color':['red','blue','green','yellow','black','white','orange','purple','brown','pink'],
 'past':['walked','ran','went','saw','took','gave','made','wrote','spoke','ate'],
}
cid={k:ids(v) for k,v in cats.items()}
print({k:len(v) for k,v in cid.items()})
dirs={}
for k,v in cid.items():
    e=E[v]; e=e/e.norm(dim=1,keepdim=True); m=e.mean(0); dirs[k]=m/m.norm()
torch.save({'cid':cid,'dirs':dirs},'/work/cats.pt')
# input-side score per layer for weekday
for L in [3,6,9,12,13,15,18]:
    w1=W(f'model.layers.{L}.feed_forward.w1.weight'); w3=W(f'model.layers.{L}.feed_forward.w3.weight')
    n=W(f'model.layers.{L}.ffn_norm.weight')
    res={}
    for k,d in dirs.items():
        x=d*n
        res[k]=(w1@x).abs()/w1.norm(dim=1)+(w3@x).abs()/w3.norm(dim=1)
    S=torch.stack(list(res.values()))
    ks=list(res.keys())
    for k in ['weekday','ordinal','past']:
        i=ks.index(k); oth=torch.cat([S[:i],S[i+1:]]).max(0).values
        sc=S[i]-0.5*oth
        top=sc.topk(256)
        print(L,k,round(top.values[:5].mean().item(),3),round(sc.mean().item(),4))

