import torch, json
def grow(L, seeds, K, other_seeds=(), name=None):
    w1=W(f'model.layers.{L}.feed_forward.w1.weight'); w2=W(f'model.layers.{L}.feed_forward.w2.weight').T
    def sc(s):
        r=w1[s].mean(0); c=w2[s].mean(0)
        return 0.5*torch.nn.functional.cosine_similarity(w1,r[None],dim=1)+0.5*torch.nn.functional.cosine_similarity(w2,c[None],dim=1)
    s=sc(list(seeds))
    if other_seeds:
        o=torch.stack([sc(list(x)) for x in other_seeds]).max(0).values
        s=s-o
    idx=s.topk(K).indices.sort().values.tolist()
    for x in seeds:
        if x not in idx: idx[-1]=x; idx=sorted(set(idx))
    if name: json.dump({'kind':'mlp_cluster','layer':L,'indices':idx},open(f'/work/{name}.json','w'))
    return s
'''
